"""Local search over a greedy week schedule (client config `improve: true`).

The greedy places shifts one at a time and never revisits them. This pass does: it changes a shift's
template or queue, removes shifts and adds shifts, keeping a move when it lowers the score

    score = sum over queues of (short_weight x short_q + miss_weight x max(0, short_q - allowed_q)) + hours

where `short_q` counts the queue's operating intervals whose agents net of breaks are below the
requirement, `allowed_q` is what the weekly attainment target (`sla_target`) still allows, and
`hours` is total scheduled elapsed hours. Every move keeps the hard rules: skills, one shift per
agent per local day, weekly hours, consecutive days, minimum rest, split-shift contracts, `min_cover`
floors, and the `max_hours_ratio` efficiency bound. Breaks are re-placed with the scheduler's own
rule after every change, so what is scored is what is written.

Deterministic: moves are tried in a fixed order.
"""
from __future__ import annotations

import math
from collections import defaultdict
from datetime import date, timedelta
from zoneinfo import ZoneInfo

import pandas as pd

from wfm import constraints
from wfm.roster import Agent
from wfm.scheduler.greedy import Shift, _covered, place_breaks, place_breaks_surplus
from wfm.scheduler.templates import eligible, templates_for
from wfm.staffing.required import in_hours


class _Week:
    def __init__(self, req: pd.DataFrame, cfg: dict, agents: list[Agent], shifts: list[Shift]):
        self.cfg = cfg
        self.z = ZoneInfo(cfg["tz"])
        self.step = timedelta(minutes=cfg["interval_minutes"])
        self.required = {q: dict(zip(g["interval_start_utc"], g["required"])) for q, g in req.groupby("queue")}
        self.queues = list(self.required)
        grid = sorted(set(req["interval_start_utc"]))
        self.days = sorted({t.astimezone(self.z).date() for t in grid})
        self.day_grid = {d: [t for t in grid if t.astimezone(self.z).date() == d] for d in self.days}
        self.ops = {(q, d): [t for t in self.day_grid[d] if in_hours(q, t, cfg)] for q in self.queues for d in self.days}
        self.floors = {(q, d): [(t, constraints.floor(q, t, cfg)) for t in self.day_grid[d]] for q in self.queues
                       for d in self.days}
        self.templates = templates_for(cfg)
        self.agents = {a.agent_id: a for a in agents}
        self.caps = cfg["weekly_hours"]
        self.max_run = cfg["max_consecutive_days"]
        self.rest = cfg.get("min_rest_hours")
        n_ops = {q: sum(len(self.ops[(q, d)]) for d in self.days) for q in self.queues}
        target = float(cfg.get("sla_target") or 0.0)
        margin = float(cfg.get("improve_margin", 0.0))
        self.allowed = {q: max(0, math.floor(n_ops[q] * (1 - min(1.0, target + margin)) + 1e-9)) for q in self.queues}
        self.short_w = float(cfg.get("improve_short_weight", 4.0))
        self.miss_w = float(cfg.get("improve_miss_weight", 200.0))
        req_hours = float(req["required"].sum()) * cfg["interval_minutes"] / 60.0
        ratio = cfg.get("max_hours_ratio")
        self.max_hours = ratio * req_hours if ratio else float("inf")
        # state
        self.by_qd: dict[tuple, list[Shift]] = defaultdict(list)
        self.by_agent: dict[str, dict[date, Shift]] = defaultdict(dict)
        for sh in shifts:
            self.by_qd[(sh.queue, sh.day)].append(sh)
            self.by_agent[sh.agent_id][sh.day] = sh
        self.short = {k: self._short(k, self.by_qd[k]) for k in self.ops}
        self.hours = sum(sh.hours for sh in shifts)
        self.hours_of = defaultdict(float)
        for sh in shifts:
            self.hours_of[sh.agent_id] += sh.hours
        self._seg_cache = {}

    # --- evaluation ---------------------------------------------------------------------------
    def _place(self, shifts: list[Shift]) -> None:
        for sh in shifts:
            sh.break_start, sh.break_minutes = None, 0
        if self.cfg["break"].get("placement", "midpoint") == "surplus":
            place_breaks_surplus(shifts, self.cfg, self.required)
        else:
            place_breaks(shifts, self.cfg)

    def _short(self, key, shifts: list[Shift]) -> int | None:
        """Short operating intervals on a queue-day (None if a floor is broken)."""
        q, d = key
        self._place(shifts)
        gross, net = defaultdict(int), defaultdict(int)
        for sh in shifts:
            for t in sh.intervals:
                gross[t] += 1
                off = sh.break_start is not None and sh.break_start < t + self.step and \
                    t < sh.break_start + timedelta(minutes=sh.break_minutes)
                net[t] += 0 if off else 1
        if any(gross[t] < f for t, f in self.floors[key] if f):
            return None
        return sum(1 for t in self.ops[key] if net[t] < self.required[q].get(t, 0))

    def _queue_short(self, overrides: dict) -> dict:
        tot = defaultdict(int)
        for k, v in self.short.items():
            tot[k[0]] += overrides.get(k, v)
        return tot

    def score(self, overrides: dict | None = None, hours: float | None = None) -> float:
        tot = self._queue_short(overrides or {})
        s = sum(self.short_w * tot[q] + self.miss_w * max(0, tot[q] - self.allowed[q]) for q in self.queues)
        return s + (self.hours if hours is None else hours)

    # --- rules --------------------------------------------------------------------------------
    def segs(self, tpl, day):
        k = (tpl.id, day)
        if k not in self._seg_cache:
            segs = tpl.segments_utc(day, self.cfg["tz"])
            self._seg_cache[k] = (segs, _covered(segs, self.day_grid[day]),
                                  sum((e - s).total_seconds() for s, e in segs) / 3600.0)
        return self._seg_cache[k]

    def allowed_for(self, aid: str, day: date, segs, hours: float, replacing: Shift | None) -> bool:
        a = self.agents[aid]
        mine = self.by_agent[aid]
        if replacing is None and day in mine:
            return False
        h = self.hours_of[aid] - (replacing.hours if replacing else 0.0) + hours
        if h > self.caps[a.contract] + 1e-9:
            return False
        if replacing is None:
            run, d = 1, day - timedelta(days=1)
            while d in mine:
                run, d = run + 1, d - timedelta(days=1)
            d = day + timedelta(days=1)
            while d in mine:
                run, d = run + 1, d + timedelta(days=1)
            if run > self.max_run:
                return False
        if self.rest:
            gap = timedelta(hours=self.rest)
            prev = [s for dd, s in mine.items() if dd < day]
            nxt = [s for dd, s in mine.items() if dd > day]
            if prev and segs[0][0] - max(prev, key=lambda s: s.day).segments[-1][1] < gap:
                return False
            if nxt and min(nxt, key=lambda s: s.day).segments[0][0] - segs[-1][1] < gap:
                return False
        return True

    # --- moves --------------------------------------------------------------------------------
    def _apply(self, key_changes: dict, new_short: dict, hours_delta: float, agent_ops) -> None:
        for k, lst in key_changes.items():
            self.by_qd[k] = lst
            self.short[k] = new_short[k]
        self.hours += hours_delta
        for op in agent_ops:
            op()

    def _try(self, changes: dict, hours_delta: float) -> tuple[bool, dict]:
        if self.hours + hours_delta > self.max_hours + 1e-9:
            return False, {}
        new = {}
        for k, lst in changes.items():
            v = self._short(k, lst)
            if v is None:
                for kk in changes:          # restore the breaks of the current state
                    self._place(self.by_qd[kk])
                return False, {}
            new[k] = v
        ok = self.score(new, self.hours + hours_delta) < self.score() - 1e-9
        if not ok:
            for kk in changes:
                self._place(self.by_qd[kk])
        return ok, new

    def round(self) -> bool:
        improved = False
        # 1. change template or queue of an existing shift, or drop it
        for key in sorted(self.by_qd, key=lambda k: (k[1], k[0])):
            for sh in sorted(list(self.by_qd[key]), key=lambda s: s.agent_id):
                if sh not in self.by_qd[key]:
                    continue
                a = self.agents[sh.agent_id]
                rest_list = [x for x in self.by_qd[key] if x is not sh]
                ok, new = self._try({key: rest_list}, -sh.hours)
                if ok:
                    self._apply({key: rest_list}, new, -sh.hours, [lambda sh=sh: self._drop(sh)])
                    improved = True
                    continue
                done = False
                for q in self.queues:
                    if q not in a.skills or done:
                        continue
                    for tpl in self.templates:
                        if (q == sh.queue and tpl.id == sh.template.id) or not eligible(tpl, a.contract, self.cfg):
                            continue
                        segs, ivs, h = self.segs(tpl, sh.day)
                        if not self.allowed_for(sh.agent_id, sh.day, segs, h, sh):
                            continue
                        new_sh = Shift(sh.agent_id, q, tpl, sh.day, segs, ivs)
                        nk = (q, sh.day)
                        changes = {key: rest_list} if nk != key else {}
                        changes[nk] = (self.by_qd[nk] if nk != key else rest_list) + [new_sh]
                        ok, new = self._try(changes, h - sh.hours)
                        if ok:
                            self._apply(changes, new, h - sh.hours,
                                        [lambda sh=sh: self._drop(sh), lambda n=new_sh: self._add(n)])
                            improved = done = True
                            break
        # 2. add a shift
        for day in self.days:
            for aid in sorted(self.agents):
                a = self.agents[aid]
                if day in self.by_agent[aid]:
                    continue
                best = None
                for q in self.queues:
                    if q not in a.skills:
                        continue
                    for tpl in self.templates:
                        if not eligible(tpl, a.contract, self.cfg):
                            continue
                        segs, ivs, h = self.segs(tpl, day)
                        if not self.allowed_for(aid, day, segs, h, None):
                            continue
                        k = (q, day)
                        new_sh = Shift(aid, q, tpl, day, segs, ivs)
                        ok, new = self._try({k: self.by_qd[k] + [new_sh]}, h)
                        if ok:
                            s = self.score(new, self.hours + h)
                            if best is None or s < best[0] - 1e-9:
                                best = (s, k, new_sh, new, h)
                if best:
                    _, k, new_sh, new, h = best
                    self._apply({k: self.by_qd[k] + [new_sh]}, new, h, [lambda n=new_sh: self._add(n)])
                    improved = True
        return improved

    def _drop(self, sh: Shift) -> None:
        del self.by_agent[sh.agent_id][sh.day]
        self.hours_of[sh.agent_id] -= sh.hours

    def _add(self, sh: Shift) -> None:
        self.by_agent[sh.agent_id][sh.day] = sh
        self.hours_of[sh.agent_id] += sh.hours

    def shifts(self) -> list[Shift]:
        out = [sh for k in sorted(self.by_qd, key=lambda k: (k[1], k[0])) for sh in self.by_qd[k]]
        for k in self.by_qd:
            self._place(self.by_qd[k])
        return sorted(out, key=lambda s: (s.day, s.segments[0][0], s.agent_id))


def improve(shifts: list[Shift], req: pd.DataFrame, cfg: dict, agents: list[Agent]) -> list[Shift]:
    w = _Week(req, cfg, agents, shifts)
    for _ in range(int(cfg.get("improve_rounds", 8))):
        if not w.round():
            break
    return w.shifts()

